import * as pdfjs from '../vendor/pdf.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('../vendor/pdf.worker.mjs',import.meta.url).href;
export async function loadPdf(bytes){return pdfjs.getDocument({data:bytes.slice(),cMapUrl:new URL('../vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('../vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('../vendor/wasm/',import.meta.url).href}).promise;}
export class PdfRenderer{
 constructor(){this.serial=0;this.task=null;this.text=null;}
 async render(doc,pageNumber,width,zoom=1){const serial=++this.serial;this.task?.cancel();this.text?.cancel();const page=await doc.getPage(pageNumber);if(serial!==this.serial)return null;const base=page.getViewport({scale:1});const viewport=page.getViewport({scale:(width/base.width)*zoom});const holder=document.querySelector('#pdf-page');const canvas=document.querySelector('#pdf-canvas');const layer=document.querySelector('#text-layer');const dpr=Math.min(window.devicePixelRatio||1,2);holder.style.width=`${viewport.width}px`;holder.style.height=`${viewport.height}px`;holder.style.minHeight='0';holder.style.setProperty('--scale-factor',viewport.scale);holder.style.setProperty('--total-scale-factor',viewport.scale);canvas.width=Math.floor(viewport.width*dpr);canvas.height=Math.floor(viewport.height*dpr);canvas.style.width=`${viewport.width}px`;canvas.style.height=`${viewport.height}px`;layer.replaceChildren();this.task=page.render({canvasContext:canvas.getContext('2d'),viewport,transform:dpr===1?null:[dpr,0,0,dpr,0,0]});try{await this.task.promise;const textContent=await page.getTextContent();if(serial!==this.serial)return null;this.text=new pdfjs.TextLayer({textContentSource:textContent,container:layer,viewport});await this.text.render();if(serial!==this.serial)return null;return{page,viewport,hasText:textContent.items.some(x=>x.str?.trim())};}catch(error){if(error.name==='RenderingCancelledException'||error.name==='AbortException')return null;throw error;}}
}
